const themeToggles=document.querySelectorAll(".js-theme-toggle"),isDark=()=>document.documentElement.classList.contains("dark");function paintToggles(){const e=isDark()?"Cambiar a modo claro":"Cambiar a modo oscuro";themeToggles.forEach(t=>{t.innerHTML=`<i class="fa-solid ${isDark()?"fa-sun":"fa-moon"}" aria-hidden="true"></i>`,t.setAttribute("aria-label",e),t.setAttribute("title",e),t.setAttribute("aria-pressed",String(isDark()))})}function toggleDarkmode(){document.documentElement.classList.toggle("dark"),document.body.classList.toggle("dark",isDark());try{localStorage.setItem("darkmode",String(isDark()))}catch{}paintToggles(),typeof window.vskRedrawMermaid=="function"&&window.vskRedrawMermaid()}themeToggles.forEach(e=>e.addEventListener("click",toggleDarkmode)),document.body.classList.toggle("dark",isDark()),paintToggles();const mobileMenu=document.getElementById("mobile-menu");function openMobileMenu(){mobileMenu.classList.remove("hidden")}function closeMobileMenu(){mobileMenu.classList.add("hidden")}